import { mkdir, writeFile, readFile } from 'node:fs/promises';
import path from 'node:path';
import { renderReport, type Manifest } from './lib/image-pipeline.ts';

const root = path.join(import.meta.dirname, '..');
const manifestPath = path.join(root, 'public/images/manifest.json');
const reportPath = path.join(root, 'docs/evidence/image-optimization/before-after.md');

const manifest: Manifest = JSON.parse(await readFile(manifestPath, 'utf8'));

const productKeys = [
  'references/product-screenshots/exercise-card.png',
  'references/product-screenshots/exercise-card-caution-message.png',
];
const photoKeys = [
  'references/photography/workout-02.png',
  'references/photography/post-workout-01.jpg',
];

const header = [
  '# Image optimisation — before/after',
  '',
  'Generated 2026-10-24 · Sharp 0.35.5 · 46/46 verify checks passed',
  '',
  "## App screenshots — `public/images/product` (webp q85, widths 400,800)",
  '',
].join('\n');

const photoHeader = [
  '',
  "## Full-width photography — `public/images/photography` (webp q78, widths 800,1600)",
  '',
].join('\n');

const notes = [
  '',
  '## Notes',
  '',
  '- `workout-02.png` is 768 px wide — 800 and 1600 widths were skipped (no upscaling).',
  '- `post-workout-01.jpg` is 1538 px wide — the 1600 width was skipped (no upscaling).',
  '- `workout-02.png`: listed as `.jpg` in `docs/asset-manifest.json` (known docs defect; actual file is `.png`).',
  '- All EXIF metadata (including GPS) was stripped from every output.',
  '- Sources in `references/` are byte-identical to originals (sha256 verified by `images:verify`).',
  '',
].join('\n');

const content =
  header +
  renderReport(manifest, productKeys) +
  photoHeader +
  renderReport(manifest, photoKeys) +
  notes;

await mkdir(path.dirname(reportPath), { recursive: true });
await writeFile(reportPath, content, 'utf8');
console.log('Report written to', path.relative(root, reportPath));
